'use client';
/**
 * 48 h history of the selected machine from the synthetic calibrated dataset
 * (public/datasets/<machineId>.json, generated by scripts/generate-datasets.ts).
 * Hidden for machines without a dataset (e.g. the second factory).
 */
import { useEffect, useMemo, useState } from 'react';
import { CartesianGrid, Line, LineChart, ReferenceArea, ReferenceLine, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import type { MachineConfig } from '@/shared/types';

interface Dataset {
  machineId: string;
  stepSec: number;
  t: number[];
  series: Record<string, number[]>;
  fault: string[];
}

const FAULT_LABEL: Record<string, string> = {
  bearing_wear: 'Bearing wear',
  cavitation: 'Cavitation',
  valve_drift: 'Filling valve drift',
  clutch_wear: 'Clutch wear',
  fan_clogged: 'Fan clogged',
  upstream_pump: 'Upstream pump fault',
  cooldown: 'Cooling down after repair',
};

const cache = new Map<string, Dataset | null>();

const fmtTime = (ms: number) =>
  new Date(ms).toLocaleString('en-GB', { weekday: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'UTC' });

export function MachineHistory({ machine, large = false }: { machine: MachineConfig; large?: boolean }) {
  const [ds, setDs] = useState<Dataset | null | undefined>(cache.get(machine.id));
  const [sensorId, setSensorId] = useState(machine.sensors[0]?.id ?? '');

  useEffect(() => {
    setSensorId(machine.sensors[0]?.id ?? '');
    if (cache.has(machine.id)) return setDs(cache.get(machine.id));
    let alive = true;
    setDs(undefined);
    fetch(`/datasets/${machine.id}.json`)
      .then((r) => (r.ok ? (r.json() as Promise<Dataset>) : null))
      .catch(() => null)
      .then((d) => {
        cache.set(machine.id, d);
        if (alive) setDs(d);
      });
    return () => {
      alive = false;
    };
  }, [machine]);

  const sensor = machine.sensors.find((s) => s.id === sensorId) ?? machine.sensors[0];
  const points = useMemo(
    () => (ds && sensor && ds.series[sensor.id] ? ds.t.map((t, i) => ({ t, v: ds.series[sensor.id]![i]!, f: ds.fault[i]! })) : []),
    [ds, sensor],
  );
  /** Fault episodes → shaded areas. Stops up to 2 h inside an episode do not split it. */
  const episodes = useMemo(() => {
    const out: Array<{ from: number; to: number; type: string }> = [];
    for (const p of points) {
      const last = out.at(-1);
      if (p.f === 'none') continue;
      if (last && last.type === p.f && p.t - last.to <= 2 * 3600_000) last.to = p.t;
      else out.push({ from: p.t, to: p.t, type: p.f });
    }
    return out;
  }, [points]);

  if (ds === null || !sensor) return <p className="text-xs text-slate-400">No historical dataset for this machine.</p>;
  const values = points.map((p) => p.v);
  const yMax = Math.max(sensor.crit * 1.05, ...values);

  return (
    <div className="rounded-md bg-slate-900/60 p-2">
      <div className="mb-1 flex items-baseline justify-between">
        <h3 className="text-xs font-semibold uppercase text-slate-400">48 h history</h3>
        <span className="text-[10px] text-slate-500">synthetic, calibrated on real data · 1 point/min</span>
      </div>
      <div role="tablist" aria-label="Sensor" className="mb-1 flex flex-wrap gap-1">
        {machine.sensors
          .filter((s) => ds?.series[s.id])
          .map((s) => (
            <button
              key={s.id}
              type="button"
              role="tab"
              aria-selected={s.id === sensor.id}
              onClick={() => setSensorId(s.id)}
              className={`rounded px-2 py-0.5 text-[11px] ${s.id === sensor.id ? 'bg-slate-700 text-slate-100' : 'text-slate-400 hover:bg-slate-800'}`}
            >
              {s.name}
            </button>
          ))}
      </div>
      {ds === undefined ? (
        <p className="py-8 text-center text-xs text-slate-500">Loading history…</p>
      ) : (
        <div className={large ? 'h-80' : 'h-40'}>
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={points} margin={{ top: 4, right: 8, bottom: 0, left: -12 }}>
              <CartesianGrid stroke="#1e293b" vertical={false} />
              <XAxis
                dataKey="t"
                type="number"
                scale="time"
                domain={['dataMin', 'dataMax']}
                tickFormatter={fmtTime}
                tick={{ fontSize: 9, fill: '#64748b' }}
                minTickGap={40}
              />
              <YAxis domain={[0, yMax]} tick={{ fontSize: 9, fill: '#64748b' }} width={40} tickFormatter={(v: number) => v.toFixed(1)} />
              {episodes.map((e) => (
                <ReferenceArea
                  key={`${e.type}-${e.from}`}
                  x1={e.from}
                  x2={e.to}
                  fill={e.type === 'cooldown' ? '#64748b' : '#ef4444'}
                  fillOpacity={0.15}
                  ifOverflow="extendDomain"
                />
              ))}
              <ReferenceLine y={sensor.warn} stroke="#eab308" strokeDasharray="3 3" />
              <ReferenceLine y={sensor.crit} stroke="#ef4444" strokeDasharray="3 3" />
              <Tooltip
                contentStyle={{ background: '#0f172a', border: '1px solid #334155', fontSize: 11 }}
                labelFormatter={(l) => fmtTime(Number(l))}
                formatter={(v, _n, item) => {
                  const f = (item?.payload as { f?: string } | undefined)?.f;
                  return [`${Number(v).toFixed(2)} ${sensor.unit}${f && f !== 'none' ? ` · ${FAULT_LABEL[f] ?? f}` : ''}`, sensor.name];
                }}
              />
              <Line type="monotone" dataKey="v" stroke="#38bdf8" dot={false} isAnimationActive={false} strokeWidth={1.5} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}
      {episodes.length > 0 && (
        <ul className="mt-1 flex flex-wrap gap-x-3 text-[10px] text-slate-400">
          {episodes
            .filter((e) => e.type !== 'cooldown')
            .map((e) => (
              <li key={`${e.type}-${e.from}`}>
                <span className="mr-1 inline-block h-2 w-2 rounded-sm bg-red-500/60" />
                {FAULT_LABEL[e.type] ?? e.type} · {fmtTime(e.from)}
              </li>
            ))}
        </ul>
      )}
    </div>
  );
}
